# RUN: llvm-mca -mtriple=riscv32-unknown-unknown -mcpu=chipsalliance-veer-eh1 --iterations=1 --timeline < %s | FileCheck %s

# A CSR read issues alone, so each pair below starts an issue group. A branch
# issues in the same cycle as the load it depends on, and an ALU op feeds the
# store data of a store in the same cycle. Two dependent ALU ops do not pair.
# A load feeds the store data of the next store one cycle later and a multiply
# two cycles later. Nothing issues in i1 after a jal or jalr.

csrr t3, mscratch
lw a0, 0(a1)
beqz a0, 1f
1:
csrr t3, mscratch
add a2, a2, a3
sw a2, 0(a1)
csrr t3, mscratch
add a4, a2, a3
add a5, a4, a3
csrr t3, mscratch
lw a6, 0(a1)
sw a6, 4(a1)
csrr t3, mscratch
lw a7, 0(a1)
mul t0, a7, a3
csrr t3, mscratch
jal zero, 2f
2:
add t1, a2, a3
csrr t3, mscratch
jalr zero, 0(t4)
add t2, a2, a3

